# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TOPLUMUN TEMELİ AİLE VE RÛM SURESİ 21. AYET İLKELERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">RÛM SURESİ 21. AYETTEKİ ÜÇ TEMEL SÜTUN</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• 1. Sekînet (Litaskünû): Ruhen huzur, güven ve sükûn bulma.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• 2. Meveddet: Karşılıklı içten sevgi, muhabbet ve dostluk.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• 3. Rahmet: Şefkat, merhamet, affedicilik ve koruyuculuk.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Nikâh Akdi: Eşlerin birbirine verdiği ağır ve kutsal söz (mîsâk).</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Emanet Bilinci: Eşler birbirine Allah\'ın emanetidir (Veda Hutbesi).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">AİLE KURUMUNUN BİREYSEL VE TOPLUMSAL İŞLEVLERİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Fıtrî İhtiyaç: İnsanın yalnızlığını giderir, aidiyet kazandırır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Neslin Korunması: Sağlıklı ve ahlaklı nesiller yetiştirir.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• İlk Okul: İman, ibadet, dil ve kültür değerlerini aktarır.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Ahlaki Kalkan: Bireyi zararlı alışkanlık ve savrulmadan korur.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Toplumsal Huzur: Güçlü aileler, güçlü ve adil toplumu oluşturur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Nisâ suresi 21. ayette evlilik akdi \'mîsâkan galîzâ\' (sağlam ve ağır bir ahit/sözleşme) olarak nitelendirilmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AİLE İÇİ İLETİŞİM İLKELERİ VE NEBEVÎ ÖRNEKLİK</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SAĞLIKLI AİLE İLETİŞİMİNİN İLKELERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Rıfk (Nezaket): Kırıcı sözden kaçınma, güler yüz ve tatlı dil.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• İstişare (Şûrâ): Aile kararlarında eş ve çocukların görüşünü alma.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Yardımlaşma: Ev içi sorumlulukları ve hayat yükünü paylaşma.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Sadakat ve Güven: Eşler arasında dürüstlük ve sır saklama.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Sabır ve Teenni: Sorunları öfkeyle değil sükûnetle çözme.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HZ. PEYGAMBER\'İN (SAV) AİLE HAYATINDAN ÖRNEKLER</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Hadis: \'Sizin en hayırlınız, ailesine karşı en hayırlı olanınızdır.\'</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• Ev İşleri: Evinde ailesinin hizmetinde bulunur, işlere yardım ederdi.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Danışma: Hudeybiye\'de eşi Ümmü Seleme ile istişare etmiştir.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Şefkat: Torunları Hasan ve Hüseyin ile oyunlar oynamıştır.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Vefa: Vefatından yıllar sonra bile Hz. Hatice\'yi hayırla anmıştır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İslam\'da aile içi şiddet, kabalık ve zulüm kesin olarak yasaklanmış; merhamet ve adalet emredilmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ANNE BABA HAKKI, ÇOCUK HAKLARI VE SILA-İ RAHİM</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ANNE BABAYA İHSAN (İSRÂ SURESİ 23-24)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Kavram: Birru\'l-Vâlideyn (Anne babaya itaat ve ihsan).</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Yaşlılıkta Görev: Onlara \'öf\' bile dememek ve azarlamamak.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Hitap: \'Kavlen Kerîmâ\' (Saygılı, gönül alıcı güzel söz).</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Dua: \'Rabbim! Küçüklüğümde beni yetiştirdikleri gibi</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• sen de onlara merhamet eyle!\' diyerek dua etmek.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">ÇOCUK HAKLARI VE AKRABALIK (SILA-İ RAHİM)</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• 1. Güzel ve anlamlı bir isim koymak, helal rızık yedirmek.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• 2. En değerli miras olan \'güzel ahlak ve terbiye\' vermek.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• 3. Çocuklar arasında sevgi ve bağışta ADALETLİ davranmak.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• 4. Sıla-i Rahim: Akrabalık bağlarını korumak ve ziyaret etmek.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• 5. Aile büyüklerine (dede, nine) hürmet ve vefa göstermek.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber: \'Allah\'tan korkun ve çocuklarınız arasında adaletli davranın!\' (Buhârî, Hibe, 13) buyurmuştur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
